import got from"got";export function submitBing(t,e,s){return got.post("https://ssl.bing.com/webmaster/api.svc/json/SubmitUrl",{searchParams:{apikey:s},headers:{"Content-Type":"application/json; charset=utf-8",Host:"ssl.bing.com"},json:{siteUrl:e,url:t},timeout:{request:3e3},responseType:"json"}).then(t=>{const e=t.body||{};if(null!==e.d)throw"提交失败";return e})}export function submitBaiDu(t,e,s){return got.post("http://data.zz.baidu.com/urls",{searchParams:{site:e,token:s},body:t,headers:{},timeout:{request:3e3},responseType:"json"}).then(t=>{const e=t.body||{};if(1!=e.success)throw"提交失败";return e})}